package gadomancymodern.maze;

import gadomancymodern.Gadomancy;
import gadomancymodern.aura.AuraEffectsConfig;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.resources.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.entity.*;
import net.minecraftforge.event.entity.player.PlayerEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import tc4revival.content.*;
import java.util.*;

/** Original single-player-per-instance maze, generated only on the server thread. */
@Mod.EventBusSubscriber(modid=Gadomancy.MOD_ID)
public class MazeSessions {
    public static final ResourceKey<Level> DIMENSION=ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,ResourceLocation.parse("gadomancy:outer_lands"));
    public static void register(){EldritchMazeSavedData.registerDimension(DIMENSION,level->MazeSessionsData.get(level).mazes);}
    public static boolean begin(ServerPlayer player,BlockPos portal){var level=player.server.getLevel(DIMENSION);if(level==null||player.level().dimension().equals(DIMENSION))return false;var data=MazeSessionsData.get(level);int max=AuraEffectsConfig.MAX_MAZES.get();if(data.sessions.containsKey(player.getUUID())||max>=0&&data.sessions.values().stream().filter(s->!s.closed).count()>=max)return false;int width=17+level.random.nextInt(2)*2,height=17+level.random.nextInt(2)*2;var layout=EldritchMazeLayout.generate(width,height,level.random.nextLong());int x=data.nextCenter;while(data.mazes.hasMazeInRange(x,29,width,height))x++;if(x>1_800_000)return false;var s=create(data,player.getUUID(),player.level().dimension(),player.position(),portal,x,29,layout);data.mazes.assignBoss(x,29,data.mazes.nextBoss(level.random));data.nextCenter=x+width+1;data.setDirty();player.setPortalCooldown(200);return s!=null;}
    public static MazeSessionsData.Session create(MazeSessionsData data,UUID owner,ResourceKey<Level> origin,net.minecraft.world.phys.Vec3 position,BlockPos source,int cx,int cz,EldritchMazeLayout layout){if(data.sessions.containsKey(owner)||!data.mazes.publish(cx,cz,layout))throw new IllegalArgumentException("Duplicate maze session");var s=new MazeSessionsData.Session();s.owner=owner;s.origin=origin;s.originPos=position;s.sourcePortal=source.immutable();s.centerX=cx;s.centerZ=cz;data.sessions.put(owner,s);data.setDirty();return s;}
    @SubscribeEvent public static void tick(TickEvent.LevelTickEvent event){if(event.phase!=TickEvent.Phase.END||!(event.level instanceof ServerLevel level)||!level.dimension().equals(DIMENSION))return;var data=MazeSessionsData.get(level);boolean built=false;for(var s:new ArrayList<>(data.sessions.values())){
        var player=level.getServer().getPlayerList().getPlayer(s.owner);
        if(s.closed){if(!built&&level.getGameTime()%4==0){cleanup(level,data,s);built=true;}continue;}
        if(player==null)continue; // A disconnect cannot silently discard the player's return position.
        if(s.entered&&!player.level().dimension().equals(DIMENSION)){close(player,false);continue;}
        if(!s.entered&&!built){buildOne(level,data,s);built=true;continue;}
        if(s.entered&&s.bossSeen&&!s.exitOpened&&(level.getGameTime()&15)==0){boolean changed=false;for(var entry:new ArrayList<>(s.bosses.entrySet())){level.getChunkAt(entry.getValue());var boss=level.getEntity(entry.getKey());if(boss!=null){if(boss.isRemoved()||boss instanceof LivingEntity living&&!living.isAlive()){s.bosses.remove(entry.getKey());changed=true;}else if(!entry.getValue().equals(boss.blockPosition())){s.bosses.put(entry.getKey(),boss.blockPosition());changed=true;}}}if(s.bosses.isEmpty())openExit(level,s);if(changed)data.setDirty();}
    }for(var player:List.copyOf(level.players()))if(!data.sessions.containsKey(player.getUUID())&&!player.getTags().contains("gadomancy_maze_test")){var origin=level.getServer().overworld();var p=origin.getSharedSpawnPos();player.teleportTo(origin,p.getX()+.5,origin.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING,p.getX(),p.getZ()),p.getZ()+.5,player.getYRot(),player.getXRot());}}
    public static void buildOne(ServerLevel level,MazeSessionsData data,MazeSessionsData.Session s){var plan=data.mazes.plan(s.centerX,s.centerZ).orElseThrow();var layout=plan.layout();while(s.buildIndex<layout.width()*layout.height()){int index=s.buildIndex++,x=index%layout.width(),z=index/layout.width();var cell=layout.cell(x,z);if(cell.packed()==0)continue;int cx=plan.originX()+x,cz=plan.originZ()+z;try{EldritchMazePlacer.generate(level,cx,cz,cell);if(cell.feature()==1)for(int y=52;y<=59;y++){var pos=new BlockPos(cx*16+8,y,cz*16+8);var state=level.getBlockState(pos);if(state.is(TCEldritch.PORTAL.get())||state.is(TCEldritch.CAP.get())||state.is(TCEldritch.OBELISK.get())||state.is(TCEldritch.OBELISK_SEGMENT.get()))level.removeBlock(pos,false);}data.mazes.markGenerated(cx,cz);data.setDirty();}catch(RuntimeException error){s.buildIndex--;data.setDirty();com.mojang.logging.LogUtils.getLogger().error("Gadomancy maze room failed; retaining session for retry",error);}return;}
        var player=level.getServer().getPlayerList().getPlayer(s.owner);if(player!=null)enter(level,data,s,player);
    }
    public static boolean enter(ServerLevel level,MazeSessionsData data,MazeSessionsData.Session s,ServerPlayer player){var source=level.getServer().getLevel(s.origin);var plan=data.mazes.plan(s.centerX,s.centerZ).orElseThrow();if(!player.getUUID().equals(s.owner)||s.entered||s.closed||s.buildIndex<plan.layout().width()*plan.layout().height())return false;if(source==null||!player.level().dimension().equals(s.origin)||!source.getBlockState(s.sourcePortal).is(Gadomancy.ADDITIONAL_PORTAL.get())){s.closed=true;s.buildIndex=0;data.setDirty();return false;}player.teleportTo(level,s.centerX*16+8.5,55,s.centerZ*16+8.5,player.getYRot(),player.getXRot());player.setPortalCooldown(200);source.removeBlock(s.sourcePortal,false);s.entered=true;data.setDirty();thaumcraft.api.ThaumcraftApiHelper.completeResearch(player,"ENTEROUTER");return true;}
    public static void openExit(ServerLevel level,MazeSessionsData.Session s){var pos=new BlockPos(s.centerX*16+8,52,s.centerZ*16+8);level.setBlockAndUpdate(pos,TCEldritch.CAP.get().defaultBlockState());level.setBlockAndUpdate(pos.above(),Gadomancy.ADDITIONAL_PORTAL.get().defaultBlockState());level.setBlockAndUpdate(pos.above(2),TCEldritch.OBELISK.get().defaultBlockState());for(int y=3;y<=6;y++)level.setBlockAndUpdate(pos.above(y),TCEldritch.OBELISK_SEGMENT.get().defaultBlockState());s.exitOpened=true;MazeSessionsData.get(level).setDirty();var player=level.getServer().getPlayerList().getPlayer(s.owner);if(player!=null)player.sendSystemMessage(net.minecraft.network.chat.Component.translatable("gadomancy.eldritch.portalSpawned").withStyle(net.minecraft.ChatFormatting.GRAY,net.minecraft.ChatFormatting.ITALIC));}
    public static boolean close(ServerPlayer player,boolean teleport){var level=player.server.getLevel(DIMENSION);if(level==null)return false;var data=MazeSessionsData.get(level);var s=data.sessions.get(player.getUUID());if(s==null||s.closed)return false;if(teleport){var target=player.server.getLevel(s.origin);if(target==null)target=player.server.overworld();player.teleportTo(target,s.originPos.x,s.originPos.y,s.originPos.z,player.getYRot(),player.getXRot());player.setPortalCooldown(200);}s.closed=true;s.buildIndex=0;data.setDirty();return true;}
    public static Optional<MazeSessionsData.Session> at(ServerLevel level,BlockPos pos){var data=MazeSessionsData.get(level);return data.sessions.values().stream().filter(s->!s.closed&&data.mazes.plan(s.centerX,s.centerZ).map(p->{int x=(pos.getX()>>4)-p.originX(),z=(pos.getZ()>>4)-p.originZ();return x>=0&&z>=0&&x<p.layout().width()&&z<p.layout().height();}).orElse(false)).findFirst();}
    @SubscribeEvent public static void joined(EntityJoinLevelEvent event){if(!(event.getLevel() instanceof ServerLevel level)||!level.dimension().equals(DIMENSION))return;var e=event.getEntity();var t=e.getType();if(t!=TCEntities.ELDRITCH_GOLEM.get()&&t!=TCEntities.ELDRITCH_WARDEN.get()&&t!=TCEntities.CULTIST_PORTAL.get()&&t!=TCEntities.TAINTACLE.get()&&t!=TCEntities.TAINTACLE_GIANT.get())return;var cell=EldritchMazeSavedData.get(level).cell(e.blockPosition().getX()>>4,e.blockPosition().getZ()>>4);if(cell.isEmpty()||cell.get().feature()<2||cell.get().feature()>5)return;at(level,e.blockPosition()).ifPresent(s->{if(s.exitOpened)return;s.bossSeen=true;s.bosses.put(e.getUUID(),e.blockPosition());MazeSessionsData.get(level).setDirty();});}
    @SubscribeEvent public static void removed(EntityLeaveLevelEvent event){if(!(event.getLevel() instanceof ServerLevel level)||!level.dimension().equals(DIMENSION))return;var e=event.getEntity();var reason=e.getRemovalReason();if(reason==null||!reason.shouldDestroy())return;var data=MazeSessionsData.get(level);for(var s:data.sessions.values())if(s.bosses.remove(e.getUUID())!=null)data.setDirty();}
    @SubscribeEvent public static void changed(PlayerEvent.PlayerChangedDimensionEvent event){if(event.getEntity() instanceof ServerPlayer player&&event.getFrom().equals(DIMENSION))close(player,false);}
    @SubscribeEvent public static void respawn(PlayerEvent.PlayerRespawnEvent event){if(event.getEntity() instanceof ServerPlayer player)close(player,false);}
    /** One abandoned room per tick slice; never overwrite another active session. */
    public static void cleanup(ServerLevel level,MazeSessionsData data,MazeSessionsData.Session s){var plan=data.mazes.plan(s.centerX,s.centerZ).orElse(null);if(plan==null){data.sessions.remove(s.owner);data.setDirty();return;}var l=plan.layout();while(s.buildIndex<l.width()*l.height()){int i=s.buildIndex++,x=i%l.width(),z=i/l.width();if(l.cell(x,z).packed()==0)continue;int cx=plan.originX()+x,cz=plan.originZ()+z;for(var entity:level.getEntitiesOfClass(Entity.class,new net.minecraft.world.phys.AABB(cx*16,45,cz*16,cx*16+16,85,cz*16+16),e->!(e instanceof net.minecraft.world.entity.player.Player)))entity.discard();for(var p:BlockPos.betweenClosed(cx*16,49,cz*16,cx*16+15,82,cz*16+15))if(!level.isEmptyBlock(p))level.setBlock(p,Blocks.AIR.defaultBlockState(),18);data.setDirty();return;}
        var tag=data.mazes.save(new CompoundTag());long center=ChunkPos.asLong(s.centerX,s.centerZ);for(String key:List.of("Plans","Bosses","Reservations")){var list=tag.getList(key,Tag.TAG_COMPOUND);list.removeIf(raw->((CompoundTag)raw).getLong("Center")==center);}tag.putLongArray("Generated",Arrays.stream(tag.getLongArray("Generated")).filter(key->{int x=ChunkPos.getX(key)-plan.originX(),z=ChunkPos.getZ(key)-plan.originZ();return x<0||z<0||x>=l.width()||z>=l.height();}).toArray());data.mazes=EldritchMazeSavedData.load(tag);data.sessions.remove(s.owner);data.setDirty();
    }
}
